      }
    }
    // distinct even values plus one odd value: an odd target can only be hit by the odd value and one partner
    const n = 100000;
    const a = r.distinct(n - 1, -499999999, 499999999).map(v => v * 2);
    const partner = r.pick(a);
    const odd = 2 * r.int(-499999999, 499999998) + 1;
    a.push(odd);
    a.sort((x, y) => x - y);
    return [a, odd + partner];
