function sortedPair(nums: number[], target: number): number[] {
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    let lo = i + 1, hi = nums.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (nums[mid] === need) return [i, mid];
      if (nums[mid] < need) lo = mid + 1;
      else hi = mid - 1;
    }
  }
  return [];
}

